package chimera.emailextractor.ui;
import javafx.application.Application; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.layout.VBox; import javafx.stage.Stage; import chimera.emailextractor.core.Extractor;
public class EmailExtractorUI extends Application { public void start(Stage s){TextArea urls=new TextArea();urls.setPromptText("URLs, one per line");ProgressBar pages=new ProgressBar(),contacts=new ProgressBar(),overall=new ProgressBar();TableView<String[]> table=new TableView<>();Button search=new Button("Search Now");search.setOnAction(e->{String[] a=urls.getText().split("\\R");for(int i=0;i<a.length;i++){String html=Extractor.fetchPage(a[i]);for(String mail:Extractor.extractEmails(html))table.getItems().add(new String[]{mail,Extractor.extractPageTitle(html),a[i],Extractor.validateEmail(mail)?"YES":"NO"});double p=(i+1)/(double)Math.max(1,a.length);pages.setProgress(p);overall.setProgress(p);contacts.setProgress(Math.min(1,table.getItems().size()/100.0));}});s.setTitle("Chimera Email Extractor");s.setScene(new Scene(new VBox(urls,pages,contacts,overall,search,table),900,600));s.show();}public static void main(String[]a){launch(a);}}
